import{z as o,x as i,o as l,c as F,q as t,j as r,D as B,d as a,s,S as n,b as A}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"数值收束","description":"","frontmatter":{"title":"数值收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/num-map.md","filePath":"llm/num-map.md","lastUpdated":1791063341000}'),p={name:"llm/num-map.md"};function d(D,E,m,C,c,g){const e=i("Mermaid");return l(),F("div",null,[E[2]||(E[2]=t('<h1 id="数值收束" tabindex="-1">数值收束 <a class="header-anchor" href="#数值收束" aria-label="Permalink to &quot;数值收束&quot;">​</a></h1><div class="epigraph"><p>十二课压成一张决策单：先选格式，再配尺子，后验预算；数值稳定是设计出来的，不是监控出来的。</p><footer>—— 据 Micikevicius et al., 2018 / 2022 与本课程十二课综合整理</footer></div><p><a href="/llm/num-longrun-health">上一课</a>把仪表盘装好，本课程至此零件齐了：格式谱系、FP8 缩放、随机舍入、量化感知训练、异常值图谱、MoE 的低精度、稀疏的数值、推理误差预算、跨硬件一致性、实验设计、健康监控。本课收束：把它们装配成一张先后分明的决策单。上游是<a href="/llm/sch-map">服务调度与多租户</a>回答「谁在什么时候用哪张卡」，下游是投机解码一类的推理深化课程；本课程回答中间这一层——卡里每个数怎么存、怎么算、怎么验。<strong>本课程到此收束。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>十一个决策点分布在格式、训练、验收三层，各自局部最优会互相拆台：块缩放解决了绑架却改变统计假设，QAT 迁就了部署却抬高训练方差，跨硬件对齐逼你钉住每一个缩放约定。没有全局顺序，团队会在错误的位置先动刀——最常见的两条弯路：训练还没稳就追 FP8 全量（把统计假设押在没验证的分布上），以及推理量化不建预算表（误差花在哪说不清，掉点了不知道回收哪一刀）。收束交付的是这张先后表。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>决策单</strong>，按「先无损后近似、先机制后参数」排序：</p><p><span class="marginnote">「三份 dtype 各自签字」翻译成白话：同一个模型里同时存在三种数字格式——矩阵乘法用窄格式（如 FP8）省算力，归一化和求和用宽格式（如 FP16/BF16）防误差累积，主权重和优化器状态用 FP32 保稳定。「签字」指把每处的选择写进实验记录，换卡换框架时逐项核对，而不是凭默认值。</span></p><ol><li><strong>格式分工</strong>：GEMM 可窄、归一化与归约留宽、主权重与优化器状态留宽——三份 dtype 各自签字（第一课）。</li><li><strong>缩放合同</strong>：逐张量延迟缩放起步；异常图谱显示绑架或突变，再上通道/块粒度（第二、五课）。</li><li><strong>更新写回</strong>：FP32 主权重是默认；显存极限处用随机舍入换偏置，优化器状态不豁免（第三课）。</li><li><strong>部署对齐</strong>：PTQ 先行，敏感层不够再 QAT；目标格式与实际核对齐（第四课）。</li><li><strong>专项数值</strong>：MoE 门控保宽、专家缩放分块（第六课）；稀疏先定结构后降精度（第七课）。</li><li><strong>推理预算表</strong>：四笔误差记账，敏感户买精度，分能力验收（第八课）。</li><li><strong>跨硬件三层验收</strong>：位级护栏、统计级迁移、任务级承诺，迁移时宽基线先行（第九课）。</li><li><strong>实验与监控</strong>：五开关单轴消融（第十课）；仪表盘按 update/weight 比与对照带告警（第十一课）。</li></ol><p>每一步拿上一步吐不出的余量。永不碰的四件事：漏乘 scale（等于随机学习率）、路由 argmax 上降精度（离散事件不进噪声框架）、无 FP32 参照轨下结论（没有锚）、跨口径比较吞吐与精度（账本不同）。</p><p><span class="marginnote">常见误区：初学者容易以为漏乘 scale 只是「精度差一点点」。实际上 scale 是把大数压回格式能表示范围的系数，漏乘等效于给一部分激活乘上一个随机大小倍数，训练就像换了一个随机学习率——曲线往往还能跑，但已经无法复现，排查代价远高于第一次就写对。</span></p>',11)),(l(),r(n,null,{default:B(()=>[s(e,{id:"mermaid-70",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E6%A0%BC%E5%BC%8F%E5%88%86%E5%B7%A5%EF%BC%9A%E4%B8%89%E4%BB%BD%20dtype%20%E7%AD%BE%E5%AD%97%22%5D%20--%3E%20S%5B%22%E7%BC%A9%E6%94%BE%E5%90%88%E5%90%8C%EF%BC%9A%E5%BB%B6%E8%BF%9F%E5%88%B0%E5%88%86%E5%9D%97%22%5D%0A%20%20S%20--%3E%20U%5B%22%E6%9B%B4%E6%96%B0%E5%86%99%E5%9B%9E%EF%BC%9A%E4%B8%BB%E6%9D%83%E9%87%8D%E6%88%96%20SR%22%5D%0A%20%20U%20--%3E%20SP%5B%22%E4%B8%93%E9%A1%B9%EF%BC%9AMoE%20%E9%97%A8%E6%8E%A7%E4%BF%9D%E5%AE%BD%20%2F%20%E7%A8%80%E7%96%8F%E5%85%88%E7%BB%93%E6%9E%84%22%5D%0A%20%20SP%20--%3E%20QAT2%5B%22%E9%83%A8%E7%BD%B2%E5%AF%B9%E9%BD%90%EF%BC%9APTQ%20%E5%85%88%E8%A1%8C%22%5D%0A%20%20QAT2%20--%3E%20BUD%5B%22%E6%8E%A8%E7%90%86%E9%A2%84%E7%AE%97%E8%A1%A8%22%5D%0A%20%20BUD%20--%3E%20HW%5B%22%E8%B7%A8%E7%A1%AC%E4%BB%B6%E4%B8%89%E5%B1%82%E9%AA%8C%E6%94%B6%22%5D%0A%20%20HW%20--%3E%20EXP%5B%22%E4%BA%94%E5%BC%80%E5%85%B3%E5%AE%9E%E9%AA%8C%20%2B%20%E4%BB%AA%E8%A1%A8%E7%9B%98%22%5D%0A%20%20EXP%20--%3E%20DONE%5B%22%E6%94%B6%E6%9D%9F%EF%BC%9A%E5%86%B3%E7%AD%96%E5%8D%95%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("顺序背后的机制是假设的分层：格式分工与主权重是不变式层，破了它们任何调优都在错的账本上算；缩放粒度、SR、QAT、块大小是参数层，按各自统计假设成立与否升降级。另一个机制是"),A("strong",null,"同一份预算在训练与推理两处兑现"),a("：训练侧守住的格式合同（scale 进检查点、amax 归约、写回偏置），正是推理预算表能「逐部件记账」的前提——训练数值混乱的模型，推理误差预算无从谈起，因为基线本身在漂。")],-1)),(l(),r(n,null,{default:B(()=>[s(e,{id:"mermaid-77",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%95%B0%E5%80%BC%E5%87%BA%E4%BA%86%E9%97%AE%E9%A2%98%EF%BC%9A%E5%85%88%E5%8A%A8%E5%93%AA%E4%B8%80%E5%B1%82%EF%BC%9F%22%5D%20--%3E%20INV%7B%22%E4%B8%8D%E5%8F%98%E5%BC%8F%E5%B1%82%E8%A2%AB%E7%A0%B4%E5%9D%8F%EF%BC%9F%22%7D%0A%20%20INV%20--%20%22%E6%98%AF%22%20--%3E%20FIX%5B%22%E5%85%88%E4%BF%AE%E6%A0%BC%E5%BC%8F%E5%88%86%E5%B7%A5%E4%B8%8E%20FP32%20%E4%B8%BB%E6%9D%83%E9%87%8D%22%5D%0A%20%20FIX%20--%3E%20ANCH%5B%22%E9%87%8D%E8%B7%91%20FP32%20%E5%8F%82%E7%85%A7%E8%BD%A8%EF%BC%8C%E9%87%8D%E6%96%B0%E9%94%9A%E5%AE%9A%E5%9F%BA%E7%BA%BF%22%5D%0A%20%20INV%20--%20%22%E5%90%A6%22%20--%3E%20PAR%5B%22%E5%8F%82%E6%95%B0%E5%B1%82%E5%8D%87%E9%99%8D%E7%BA%A7%EF%BC%9A%E7%BC%A9%E6%94%BE%E7%B2%92%E5%BA%A6%20%2F%20SR%20%2F%20QAT%20%2F%20%E5%9D%97%E5%A4%A7%E5%B0%8F%22%5D%0A%20%20PAR%20--%3E%20ONE%5B%22%E4%B8%80%E6%AC%A1%E5%8F%AA%E5%8A%A8%E4%B8%80%E4%B8%AA%E5%BC%80%E5%85%B3%22%5D%0A%20%20ONE%20--%3E%20OK%7B%22%E6%8C%87%E6%A0%87%E5%9B%9E%E5%88%B0%E5%AF%B9%E7%85%A7%E5%B8%A6%E5%86%85%EF%BC%9F%22%7D%0A%20%20OK%20--%20%22%E6%98%AF%22%20--%3E%20LOCK%5B%22%E7%AD%BE%E5%AD%97%E9%80%9A%E8%BF%87%EF%BC%8C%E8%BF%9B%E4%B8%8B%E4%B8%80%E6%A1%A3%22%5D%0A%20%20OK%20--%20%22%E5%90%A6%22%20--%3E%20ROLL%5B%22%E5%9B%9E%E6%BB%9A%EF%BC%8C%E6%8D%A2%E4%B8%8B%E4%B8%80%E4%B8%AA%E5%8F%82%E6%95%B0%E5%86%8D%E8%AF%95%22%5D%0A%20%20ROLL%20--%3E%20PAR%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=t('<p><span class="marginnote">数字实例：假设推理预算表允许总共 1% 的能力下降，四笔误差（权重、激活、KV 缓存、注意力累积）各预留约 0.25%；若权重量化一项实测就吃掉 0.9%，说明该给敏感层买回精度（如局部升到 BF16），而不是继续把别的部件往下压——预算超支要找到花超的那一户，不能全楼分摊。</span></p><p><span class="marginnote">一张自检表：若只能做三件事——把三份 dtype 签清、给每个缩放张量挂上 amax 监控与溢出计数、为推理建一张四行预算表。多数团队在这三步之前就已避开绝大多数数值事故；后面的每一档都要求先证明前面拿不出来。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>这张单子有时效。格式侧：微缩放与下一代块格式的普及会把「缩放合同」从工程自觉变成硬件默认，第 2 步的权重大幅前移；负载侧：MoE 与长上下文把异常图谱按专家与位置切分，监控面继续加宽；硬件侧：跨厂商混合集群放大第九课的合同成本。收束不是终点：数值管好之后，瓶颈移向解码与投机，移向更长上下文的系统工程——本课程交付的是「数」这一层的地图，地图之外的路，由相邻课程接棒。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>决策单八步：格式分工 → 缩放合同 → 更新写回 → 专项数值 → 部署对齐 → 预算表 → 三层验收 → 实验与监控。</li><li>不变式层（三份 dtype、主权重）先于参数层（粒度、SR、QAT）；每步拿上一步吐不出的余量。</li><li>四件永不碰：漏乘 scale、量化路由、无参照下结论、跨口径比较。</li><li>训练的格式合同是推理预算表的前提，同一份预算两处兑现。</li><li>出处：本课程十二课综合口径；底层文献锚点为 Micikevicius et al., 2018（混合精度）与 2022（FP8 格式）。</li></ul>',6))])}const P=o(p,[["render",d]]);export{u as __pageData,P as default};
